ACCOUNTING = Path("artifacts/api-server/src/lib/position-accounting.ts")

def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Could not patch {label}: expected block not found")
    return text.replace(old, new, 1)

schema = SCHEMA.read_text()
schema = replace_once(schema, '    entryPriceSol: doublePrecision("entry_price_sol"),\n    tpFired: boolean("tp_fired").notNull().default(false),\n', '    entryPriceSol: doublePrecision("entry_price_sol"),\n    positionCostSol: doublePrecision("position_cost_sol").notNull().default(0),\n    totalInvestedSol: doublePrecision("total_invested_sol").notNull().default(0),\n    realizedPnlSol: doublePrecision("realized_pnl_sol").notNull().default(0),\n    tpFired: boolean("tp_fired").notNull().default(false),\n', 'PnL schema fields')
SCHEMA.write_text(schema)

engine = ENGINE.read_text()
engine = replace_once(engine, 'export async function walletTokenBalance(\n  address: string,\n  mint: string,\n): Promise<number> {\n', 'export async function transactionSolDelta(\n  address: string,\n  signature: string,\n): Promise<number> {\n  const owner = new PublicKey(address);\n\n  const transaction = await executionConnection.getTransaction(\n    signature,\n    {\n      commitment: "confirmed",\n      maxSupportedTransactionVersion: 0,\n    },\n  );\n\n  if (!transaction?.meta) {\n    throw new Error("Confirmed transaction details are unavailable");\n  }\n\n  const accountKeys = transaction.transaction.message.getAccountKeys({\n    accountKeysFromLookups:\n      transaction.meta.loadedAddresses ?? undefined,\n  });\n\n  let ownerIndex = -1;\n\n  for (let index = 0; index < accountKeys.length; index += 1) {\n    const key = accountKeys.get(index);\n    if (key?.equals(owner)) {\n      ownerIndex = index;\n      break;\n    }\n  }\n\n  if (ownerIndex < 0) {\n    throw new Error("Wallet was not found in the confirmed transaction");\n  }\n\n  const before = transaction.meta.preBalances[ownerIndex];\n  const after = transaction.meta.postBalances[ownerIndex];\n\n  if (before == null || after == null) {\n    throw new Error("Transaction SOL balance delta is unavailable");\n  }\n\n  return (after - before) / LAMPORTS_PER_SOL;\n}\n\nexport async function walletTokenBalance(\n  address: string,\n  mint: string,\n): Promise<number> {\n', 'transaction SOL delta')
ENGINE.write_text(engine)

routes = ROUTES.read_text()
routes = replace_once(routes, 'import {\n  currentPriceSol,\n  executeBuy,\n  executeSellPercent,\n  walletSolBalance,\n  walletTokenBalance,\n  withdrawSol,\n  walletDeletionState,\n} from "../lib/execution-engine";\n', 'import {\n  currentPriceSol,\n  executeBuy,\n  executeSellPercent,\n  walletSolBalance,\n  walletTokenBalance,\n  withdrawSol,\n  walletDeletionState,\n} from "../lib/execution-engine";\nimport {\n  financialSnapshot,\n  recordBuyAccounting,\n  recordSellAccounting,\n} from "../lib/position-accounting";\n', 'position accounting import')
routes = replace_once(routes, 'async function finishManualSell(\n  strategy: Awaited<ReturnType<typeof findStrategy>>,\n  percentage: number,\n  signature: string,\n) {\n  if (!strategy) return;\n\n  const fullExit = percentage >= 100;\n\n  await db\n    .update(executionStrategiesTable)\n    .set({\n      enabled: fullExit ? false : strategy.enabled,\n      entryPriceSol: fullExit\n        ? null\n        : strategy.entryPriceSol,\n      tpFired: fullExit\n        ? false\n        : strategy.tpFired,\n      state: fullExit\n        ? "closed"\n        : strategy.enabled\n          ? "watching"\n          : "idle",\n      lastTrigger: "manual-sell",\n      lastSignature: signature,\n      lastError: null,\n      updatedAt: new Date(),\n    })\n    .where(eq(executionStrategiesTable.id, strategy.id));\n}\n\nasync function tokenBalanceAfterBuy(\n  address: string,\n  mint: string,\n  beforeBalance: number,\n): Promise<number> {\n  let latest = beforeBalance;\n\n  for (let attempt = 0; attempt < 4; attempt += 1) {\n    latest = await walletTokenBalance(address, mint);\n    if (latest > beforeBalance) return latest;\n\n    if (attempt < 3) {\n      await new Promise((resolve) => setTimeout(resolve, 300));\n    }\n  }\n\n  return latest;\n}\n\nasync function updateWeightedEntryAfterBuy(\n  walletId: string,\n  address: string,\n  mint: string,\n  amountSol: number,\n  beforeBalance: number,\n  previousStrategy: Awaited<ReturnType<typeof findStrategy>>,\n) {\n  const afterBalance = await tokenBalanceAfterBuy(\n    address,\n    mint,\n    beforeBalance,\n  );\n\n  const acquired = Math.max(0, afterBalance - beforeBalance);\n\n  let entryPriceSol: number;\n\n  if (acquired > 0) {\n    if (\n      beforeBalance > 0 &&\n      previousStrategy?.entryPriceSol &&\n      previousStrategy.entryPriceSol > 0\n    ) {\n      const priorCost =\n        beforeBalance * previousStrategy.entryPriceSol;\n\n      entryPriceSol =\n        (priorCost + amountSol) / afterBalance;\n    } else if (beforeBalance <= 0) {\n      entryPriceSol = amountSol / acquired;\n    } else {\n      const current = await currentPriceSol(mint);\n      const estimatedPriorCost = beforeBalance * current;\n      entryPriceSol =\n        (estimatedPriorCost + amountSol) / afterBalance;\n    }\n  } else {\n    entryPriceSol = await currentPriceSol(mint);\n  }\n\n  if (!Number.isFinite(entryPriceSol) || entryPriceSol <= 0) {\n    throw new Error("Could not calculate the weighted entry price");\n  }\n\n  const enabled = previousStrategy?.enabled ?? false;\n\n  await db\n    .insert(executionStrategiesTable)\n    .values({\n      walletId,\n      mint,\n      enabled,\n      entryPriceSol,\n      tpFired: false,\n      state: enabled ? "watching" : "idle",\n      updatedAt: new Date(),\n    })\n    .onConflictDoUpdate({\n      target: [\n        executionStrategiesTable.walletId,\n        executionStrategiesTable.mint,\n      ],\n      set: {\n        entryPriceSol,\n        tpFired: false,\n        state: enabled ? "watching" : "idle",\n        lastTrigger: null,\n        lastSignature: null,\n        lastError: null,\n        updatedAt: new Date(),\n      },\n    });\n}\n', '', 'old accounting helpers')
routes = replace_once(routes, '  const rows = await Promise.all(\n    wallets.map(async (wallet) => {\n      let sol = 0;\n      try {\n        sol = await walletSolBalance(wallet.address);\n      } catch {\n        sol = 0;\n      }\n\n      const strategy = strategyByWallet.get(wallet.id) ?? null;\n      const pnl =\n        strategy?.entryPriceSol &&\n        priceSol != null\n          ? ((priceSol - strategy.entryPriceSol) /\n              strategy.entryPriceSol) *\n            100\n          : null;\n\n      return {\n        id: wallet.id,\n        address: wallet.address,\n        enabled: wallet.enabled,\n        sol,\n        strategy,\n        pnl,\n      };\n    }),\n  );\n\n  res.json({\n    mint,\n    priceSol,\n    priceError,\n    wallets: rows,\n  });\n', '  const rows = await Promise.all(\n    wallets.map(async (wallet) => {\n      let sol = 0;\n      let tokenBalance = 0;\n\n      try {\n        sol = await walletSolBalance(wallet.address);\n      } catch {\n        sol = 0;\n      }\n\n      try {\n        tokenBalance = await walletTokenBalance(\n          wallet.address,\n          mint,\n        );\n      } catch {\n        tokenBalance = 0;\n      }\n\n      const strategy = strategyByWallet.get(wallet.id) ?? null;\n      const financials = financialSnapshot(\n        strategy,\n        tokenBalance,\n        priceSol,\n      );\n\n      return {\n        id: wallet.id,\n        address: wallet.address,\n        enabled: wallet.enabled,\n        sol,\n        tokenBalance,\n        strategy,\n        pnl: financials.totalPnlPct,\n        ...financials,\n      };\n    }),\n  );\n\n  const realizedPnlSol = rows.reduce(\n    (sum, wallet) => sum + wallet.realizedPnlSol,\n    0,\n  );\n\n  const totalInvestedSol = rows.reduce(\n    (sum, wallet) => sum + wallet.totalInvestedSol,\n    0,\n  );\n\n  const canValueOpenPositions =\n    priceSol != null &&\n    rows.every(\n      (wallet) =>\n        wallet.tokenBalance <= 0 ||\n        wallet.unrealizedPnlSol != null,\n    );\n\n  const unrealizedPnlSol = canValueOpenPositions\n    ? rows.reduce(\n        (sum, wallet) =>\n          sum + (wallet.unrealizedPnlSol ?? 0),\n        0,\n      )\n    : null;\n\n  const totalPnlSol =\n    unrealizedPnlSol == null\n      ? null\n      : realizedPnlSol + unrealizedPnlSol;\n\n  const totalPnlPct =\n    totalPnlSol != null && totalInvestedSol > 0\n      ? (totalPnlSol / totalInvestedSol) * 100\n      : null;\n\n  res.json({\n    mint,\n    priceSol,\n    priceError,\n    summary: {\n      totalPnlSol,\n      totalPnlPct,\n      realizedPnlSol,\n      unrealizedPnlSol,\n      totalInvestedSol,\n    },\n    wallets: rows,\n  });\n', 'state PnL summary')
routes = replace_once(routes, '        await updateWeightedEntryAfterBuy(\n          wallet.id,\n          address,\n          mint,\n          amount,\n          beforeBalance,\n          strategy,\n        );\n', '        await recordBuyAccounting({\n          walletId: wallet.id,\n          address,\n          mint,\n          amountSol: amount,\n          beforeBalance,\n          previousStrategy: strategy,\n        });\n', 'individual buy accounting')
routes = replace_once(routes, '      signature = await executeSellPercent(\n        keypair,\n        mint,\n        percentage,\n      );\n\n      await finishManualSell(\n        strategy,\n        percentage,\n        signature,\n      );\n', '      const beforeBalance = await walletTokenBalance(\n        address,\n        mint,\n      );\n\n      signature = await executeSellPercent(\n        keypair,\n        mint,\n        percentage,\n      );\n\n      try {\n        await recordSellAccounting({\n          strategy,\n          address,\n          mint,\n          beforeBalance,\n          percentage,\n          signature,\n          trigger: "manual-sell",\n          forceDisable: false,\n        });\n      } catch (trackingError) {\n        req.log.error(\n          { err: trackingError, address, mint, signature },\n          "SELL succeeded but P&L accounting failed",\n        );\n\n        if (strategy) {\n          const fullExit = percentage >= 100;\n\n          await db\n            .update(executionStrategiesTable)\n            .set({\n              enabled: fullExit ? false : strategy.enabled,\n              entryPriceSol: fullExit\n                ? null\n                : strategy.entryPriceSol,\n              positionCostSol: fullExit\n                ? 0\n                : strategy.positionCostSol,\n              state: fullExit\n                ? "closed"\n                : strategy.enabled\n                  ? "watching"\n                  : "idle",\n              lastTrigger: "manual-sell",\n              lastSignature: signature,\n              lastError:\n                trackingError instanceof Error\n                  ? trackingError.message\n                  : String(trackingError),\n              updatedAt: new Date(),\n            })\n            .where(eq(executionStrategiesTable.id, strategy.id));\n        }\n      }\n', 'individual sell accounting')
routes = replace_once(routes, '          await updateWeightedEntryAfterBuy(\n            wallet.id,\n            wallet.address,\n            mint,\n            buyAmount,\n            beforeBalance,\n            strategy,\n          );\n', '          await recordBuyAccounting({\n            walletId: wallet.id,\n            address: wallet.address,\n            mint,\n            amountSol: buyAmount,\n            beforeBalance,\n            previousStrategy: strategy,\n          });\n', 'buy-all accounting')
routes = replace_once(routes, '        signature = await executeSellPercent(\n          keypair,\n          mint,\n          sellPercentage,\n        );\n\n        await finishManualSell(\n          strategy,\n          sellPercentage,\n          signature,\n        );\n', '        const beforeBalance = await walletTokenBalance(\n          wallet.address,\n          mint,\n        );\n\n        signature = await executeSellPercent(\n          keypair,\n          mint,\n          sellPercentage,\n        );\n\n        try {\n          await recordSellAccounting({\n            strategy,\n            address: wallet.address,\n            mint,\n            beforeBalance,\n            percentage: sellPercentage,\n            signature,\n            trigger: "manual-sell-all",\n            forceDisable: false,\n          });\n        } catch (trackingError) {\n          req.log.error(\n            {\n              err: trackingError,\n              address: wallet.address,\n              mint,\n              signature,\n            },\n            "SELL ALL trade succeeded but P&L accounting failed",\n          );\n\n          if (strategy) {\n            const fullExit = sellPercentage >= 100;\n\n            await db\n              .update(executionStrategiesTable)\n              .set({\n                enabled: fullExit ? false : strategy.enabled,\n                entryPriceSol: fullExit\n                  ? null\n                  : strategy.entryPriceSol,\n                positionCostSol: fullExit\n                  ? 0\n                  : strategy.positionCostSol,\n                state: fullExit\n                  ? "closed"\n                  : strategy.enabled\n                    ? "watching"\n                    : "idle",\n                lastTrigger: "manual-sell-all",\n                lastSignature: signature,\n                lastError:\n                  trackingError instanceof Error\n                    ? trackingError.message\n                    : String(trackingError),\n                updatedAt: new Date(),\n              })\n              .where(eq(executionStrategiesTable.id, strategy.id));\n          }\n        }\n', 'sell-all accounting')
ROUTES.write_text(routes)

worker = WORKER.read_text()
worker = replace_once(worker, 'import {\n  currentPriceSol,\n  executeSellPercent,\n} from "./execution-engine";\n', 'import {\n  currentPriceSol,\n  executeSellPercent,\n  walletTokenBalance,\n} from "./execution-engine";\nimport { recordSellAccounting } from "./position-accounting";\n', 'worker accounting import')
worker = replace_once(worker, '        const signature = await executeSellPercent(\n          keypair,\n          strategy.mint,\n          sellPct,\n        );\n\n        const fullExit = sellPct >= 100;\n        const tpFired = trigger === "tp" ? true : strategy.tpFired;\n\n        await db\n          .update(executionStrategiesTable)\n          .set({\n            enabled:\n              trigger === "sl" || fullExit\n                ? false\n                : strategy.enabled,\n            tpFired,\n            state:\n              trigger === "sl" || fullExit\n                ? "closed"\n                : "watching",\n            lastSignature: signature,\n            lastError: null,\n            updatedAt: new Date(),\n          })\n          .where(eq(executionStrategiesTable.id, strategy.id));\n', '        const beforeBalance = await walletTokenBalance(\n          wallet.address,\n          strategy.mint,\n        );\n\n        const signature = await executeSellPercent(\n          keypair,\n          strategy.mint,\n          sellPct,\n        );\n\n        await recordSellAccounting({\n          strategy,\n          address: wallet.address,\n          mint: strategy.mint,\n          beforeBalance,\n          percentage: sellPct,\n          signature,\n          trigger,\n          forceDisable: trigger === "sl",\n          tpFired:\n            trigger === "tp"\n              ? true\n              : strategy.tpFired,\n        });\n', 'AUTO sell accounting')
WORKER.write_text(worker)

home = HOME.read_text()
home = replace_once(home, 'type Strategy = {\n  enabled: boolean;\n  tpPct: number;\n  tpSellPct: number;\n  slPct: number;\n  slSellPct: number;\n  entryPriceSol?: number | null;\n  state?: string;\n', 'type Strategy = {\n  enabled: boolean;\n  tpPct: number;\n  tpSellPct: number;\n  slPct: number;\n  slSellPct: number;\n  entryPriceSol?: number | null;\n  positionCostSol?: number;\n  totalInvestedSol?: number;\n  realizedPnlSol?: number;\n  state?: string;\n', 'frontend strategy PnL fields')
home = replace_once(home, '  strategy?: Strategy | null;\n  pnl?: number | null;\n};\n', '  strategy?: Strategy | null;\n  pnl?: number | null;\n  tokenBalance?: number;\n  positionCostSol?: number;\n  totalInvestedSol?: number;\n  realizedPnlSol?: number;\n  unrealizedPnlSol?: number | null;\n  totalPnlSol?: number | null;\n  totalPnlPct?: number | null;\n};\n\ntype PnlSummary = {\n  totalPnlSol: number | null;\n  totalPnlPct: number | null;\n  realizedPnlSol: number;\n  unrealizedPnlSol: number | null;\n  totalInvestedSol: number;\n};\n', 'frontend wallet PnL fields')
home = replace_once(home, "const numberText = (value: number | null | undefined, digits = 4) =>\n  value == null || !Number.isFinite(value) ? '—' : value.toFixed(digits);\n", "const numberText = (value: number | null | undefined, digits = 4) =>\n  value == null || !Number.isFinite(value) ? '—' : value.toFixed(digits);\n\nconst signedSolText = (\n  value: number | null | undefined,\n  digits = 4,\n) =>\n  value == null || !Number.isFinite(value)\n    ? '—'\n    : `${value > 0 ? '+' : ''}${value.toFixed(digits)} SOL`;\n\nconst signedPctText = (\n  value: number | null | undefined,\n  digits = 2,\n) =>\n  value == null || !Number.isFinite(value)\n    ? '—'\n    : `${value > 0 ? '+' : ''}${value.toFixed(digits)}%`;\n", 'PnL formatters')
home = replace_once(home, "  const [priceSol, setPriceSol] = useState<number | null>(null);\n  const [priceError, setPriceError] = useState('');\n\n  const [buyAmount, setBuyAmount] = useState('0.01');\n", "  const [priceSol, setPriceSol] = useState<number | null>(null);\n  const [priceError, setPriceError] = useState('');\n  const [pnlSummary, setPnlSummary] = useState<PnlSummary | null>(null);\n\n  const [buyAmount, setBuyAmount] = useState('0.01');\n", 'PnL summary state')
home = replace_once(home, "        setWallets(data.wallets || []);\n        setPriceSol(data.priceSol ?? null);\n        setPriceError(data.priceError || '');\n\n        setDrafts((prev) => {\n", "        setWallets(data.wallets || []);\n        setPriceSol(data.priceSol ?? null);\n        setPriceError(data.priceError || '');\n        setPnlSummary(data.summary || null);\n\n        setDrafts((prev) => {\n", 'refresh summary')
home = replace_once(home, "        const data = await api('/api/execution/wallets');\n        setWallets(data.wallets || []);\n", "        const data = await api('/api/execution/wallets');\n        setWallets(data.wallets || []);\n        setPnlSummary(null);\n", 'clear summary without mint')
home = replace_once(home, "              onChange={(e) => {\n                setMint(e.target.value);\n                setMintState({ status: 'idle' });\n              }}\n", "              onChange={(e) => {\n                setMint(e.target.value);\n                setMintState({ status: 'idle' });\n                setPnlSummary(null);\n              }}\n", 'clear summary on mint edit')
home = replace_once(home, '        <section className="section">\n          <div className="section-head"><span>Trade all</span></div>\n\n          <div className="global-grid">\n', '        <section className="section">\n          <div className="section-head"><span>Trade all</span></div>\n\n          <div className="pnl-summary">\n            <div className="pnl-summary-main">\n              <span>TOTAL P&amp;L</span>\n              <strong>\n                {signedSolText(pnlSummary?.totalPnlSol)}\n                <b>{signedPctText(pnlSummary?.totalPnlPct)}</b>\n              </strong>\n            </div>\n\n            <div className="pnl-summary-split">\n              <span>\n                REALIZED\n                <b>{signedSolText(pnlSummary?.realizedPnlSol)}</b>\n              </span>\n              <span>\n                UNREALIZED\n                <b>{signedSolText(pnlSummary?.unrealizedPnlSol)}</b>\n              </span>\n            </div>\n          </div>\n\n          <div className="global-grid">\n', 'Trade all PnL summary UI')
HOME.write_text(home)

css = CSS.read_text()
css += "\n\n/* v7.1 compact aggregate P&L */\n.pnl-summary {\n  margin:0 0 9px;\n  padding:7px 0 8px;\n  border-bottom:1px solid #ededed;\n}\n\n.pnl-summary-main {\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:10px;\n  font-size:8px;\n  font-weight:750;\n}\n\n.pnl-summary-main strong {\n  display:flex;\n  align-items:baseline;\n  gap:7px;\n  font-size:11px;\n  white-space:nowrap;\n}\n\n.pnl-summary-main strong b {\n  font-size:8px;\n  font-weight:650;\n}\n\n.pnl-summary-split {\n  display:flex;\n  justify-content:space-between;\n  gap:12px;\n  margin-top:5px;\n  color:#888;\n  font-size:7px;\n}\n\n.pnl-summary-split span {\n  display:flex;\n  align-items:center;\n  gap:5px;\n}\n\n.pnl-summary-split b {\n  color:#555;\n  font-weight:650;\n}\n\nhtml[data-theme='dark'] .pnl-summary {\n  border-color:#262626;\n}\n\nhtml[data-theme='dark'] .pnl-summary-split {\n  color:#777;\n}\n\nhtml[data-theme='dark'] .pnl-summary-split b {\n  color:#aaa;\n}\n"
CSS.write_text(css)

ACCOUNTING.write_text('import { eq } from "drizzle-orm";\nimport {\n  db,\n  executionStrategiesTable,\n  type ExecutionStrategy,\n} from "@workspace/db";\nimport {\n  currentPriceSol,\n  transactionSolDelta,\n  walletTokenBalance,\n} from "./execution-engine";\n\nconst BALANCE_EPSILON = 1e-12;\n\nfunction storedPositionCost(\n  strategy: ExecutionStrategy | null | undefined,\n  tokenBalance: number,\n): number {\n  if (!strategy) return 0;\n\n  if (\n    Number.isFinite(strategy.positionCostSol) &&\n    strategy.positionCostSol > 0\n  ) {\n    return strategy.positionCostSol;\n  }\n\n  if (\n    tokenBalance > 0 &&\n    strategy.entryPriceSol &&\n    strategy.entryPriceSol > 0\n  ) {\n    return tokenBalance * strategy.entryPriceSol;\n  }\n\n  return 0;\n}\n\nfunction storedTotalInvested(\n  strategy: ExecutionStrategy | null | undefined,\n  fallbackCost: number,\n): number {\n  if (\n    strategy &&\n    Number.isFinite(strategy.totalInvestedSol) &&\n    strategy.totalInvestedSol > 0\n  ) {\n    return strategy.totalInvestedSol;\n  }\n\n  return fallbackCost;\n}\n\nasync function waitForTokenBalance(\n  address: string,\n  mint: string,\n  beforeBalance: number,\n  direction: "up" | "down",\n): Promise<number> {\n  let latest = beforeBalance;\n\n  for (let attempt = 0; attempt < 6; attempt += 1) {\n    latest = await walletTokenBalance(address, mint);\n\n    if (\n      (direction === "up" && latest > beforeBalance) ||\n      (direction === "down" && latest < beforeBalance)\n    ) {\n      return latest;\n    }\n\n    if (attempt < 5) {\n      await new Promise((resolve) => setTimeout(resolve, 350));\n    }\n  }\n\n  return latest;\n}\n\nexport function financialSnapshot(\n  strategy: ExecutionStrategy | null | undefined,\n  tokenBalance: number,\n  priceSol: number | null,\n) {\n  const positionCostSol = storedPositionCost(\n    strategy,\n    tokenBalance,\n  );\n\n  const totalInvestedSol = storedTotalInvested(\n    strategy,\n    positionCostSol,\n  );\n\n  const realizedPnlSol =\n    strategy?.realizedPnlSol &&\n    Number.isFinite(strategy.realizedPnlSol)\n      ? strategy.realizedPnlSol\n      : 0;\n\n  let unrealizedPnlSol: number | null;\n\n  if (tokenBalance <= BALANCE_EPSILON) {\n    unrealizedPnlSol = 0;\n  } else if (priceSol != null && positionCostSol > 0) {\n    unrealizedPnlSol =\n      tokenBalance * priceSol - positionCostSol;\n  } else {\n    unrealizedPnlSol = null;\n  }\n\n  const totalPnlSol =\n    unrealizedPnlSol == null\n      ? null\n      : realizedPnlSol + unrealizedPnlSol;\n\n  const totalPnlPct =\n    totalPnlSol != null && totalInvestedSol > 0\n      ? (totalPnlSol / totalInvestedSol) * 100\n      : null;\n\n  return {\n    positionCostSol,\n    totalInvestedSol,\n    realizedPnlSol,\n    unrealizedPnlSol,\n    totalPnlSol,\n    totalPnlPct,\n  };\n}\n\nexport async function recordBuyAccounting({\n  walletId,\n  address,\n  mint,\n  amountSol,\n  beforeBalance,\n  previousStrategy,\n}: {\n  walletId: string;\n  address: string;\n  mint: string;\n  amountSol: number;\n  beforeBalance: number;\n  previousStrategy: ExecutionStrategy | null;\n}) {\n  let afterBalance = await waitForTokenBalance(\n    address,\n    mint,\n    beforeBalance,\n    "up",\n  );\n\n  const newCycle = beforeBalance <= BALANCE_EPSILON;\n\n  const previousCost = newCycle\n    ? 0\n    : storedPositionCost(\n        previousStrategy,\n        beforeBalance,\n      );\n\n  const previousInvested = newCycle\n    ? 0\n    : storedTotalInvested(\n        previousStrategy,\n        previousCost,\n      );\n\n  const realizedPnlSol = newCycle\n    ? 0\n    : previousStrategy?.realizedPnlSol ?? 0;\n\n  const positionCostSol = previousCost + amountSol;\n  const totalInvestedSol =\n    previousInvested + amountSol;\n\n  if (afterBalance <= beforeBalance) {\n    const current = await currentPriceSol(mint);\n    const estimatedAcquired = amountSol / current;\n    afterBalance = beforeBalance + estimatedAcquired;\n  }\n\n  const entryPriceSol =\n    positionCostSol / afterBalance;\n\n  if (\n    !Number.isFinite(entryPriceSol) ||\n    entryPriceSol <= 0\n  ) {\n    throw new Error(\n      "Could not calculate the weighted entry price",\n    );\n  }\n\n  const enabled = previousStrategy?.enabled ?? false;\n\n  await db\n    .insert(executionStrategiesTable)\n    .values({\n      walletId,\n      mint,\n      enabled,\n      entryPriceSol,\n      positionCostSol,\n      totalInvestedSol,\n      realizedPnlSol,\n      tpFired: false,\n      state: enabled ? "watching" : "idle",\n      updatedAt: new Date(),\n    })\n    .onConflictDoUpdate({\n      target: [\n        executionStrategiesTable.walletId,\n        executionStrategiesTable.mint,\n      ],\n      set: {\n        entryPriceSol,\n        positionCostSol,\n        totalInvestedSol,\n        realizedPnlSol,\n        tpFired: false,\n        state: enabled ? "watching" : "idle",\n        lastTrigger: null,\n        lastSignature: null,\n        lastError: null,\n        updatedAt: new Date(),\n      },\n    });\n}\n\nexport async function recordSellAccounting({\n  strategy,\n  address,\n  mint,\n  beforeBalance,\n  percentage,\n  signature,\n  trigger,\n  forceDisable,\n  tpFired,\n}: {\n  strategy: ExecutionStrategy | null;\n  address: string;\n  mint: string;\n  beforeBalance: number;\n  percentage: number;\n  signature: string;\n  trigger: string;\n  forceDisable: boolean;\n  tpFired?: boolean;\n}) {\n  if (!strategy) return;\n\n  const afterBalance = await waitForTokenBalance(\n    address,\n    mint,\n    beforeBalance,\n    "down",\n  );\n\n  let soldFraction =\n    beforeBalance > BALANCE_EPSILON\n      ? (beforeBalance - afterBalance) / beforeBalance\n      : percentage / 100;\n\n  if (\n    !Number.isFinite(soldFraction) ||\n    soldFraction <= 0\n  ) {\n    soldFraction = percentage / 100;\n  }\n\n  soldFraction = Math.min(\n    1,\n    Math.max(0, soldFraction),\n  );\n\n  const previousCost = storedPositionCost(\n    strategy,\n    beforeBalance,\n  );\n\n  const totalInvestedSol = storedTotalInvested(\n    strategy,\n    previousCost,\n  );\n\n  const costSold = previousCost * soldFraction;\n  const proceedsSol = await transactionSolDelta(\n    address,\n    signature,\n  );\n\n  const realizedPnlSol =\n    (strategy.realizedPnlSol ?? 0) +\n    proceedsSol -\n    costSold;\n\n  const fullExit =\n    percentage >= 100 ||\n    afterBalance <= BALANCE_EPSILON;\n\n  const positionCostSol = fullExit\n    ? 0\n    : Math.max(0, previousCost - costSold);\n\n  const entryPriceSol =\n    fullExit || afterBalance <= BALANCE_EPSILON\n      ? null\n      : positionCostSol / afterBalance;\n\n  const enabled =\n    fullExit || forceDisable\n      ? false\n      : strategy.enabled;\n\n  await db\n    .update(executionStrategiesTable)\n    .set({\n      enabled,\n      entryPriceSol,\n      positionCostSol,\n      totalInvestedSol,\n      realizedPnlSol,\n      tpFired: fullExit\n        ? false\n        : tpFired ?? strategy.tpFired,\n      state: fullExit\n        ? "closed"\n        : enabled\n          ? "watching"\n          : "idle",\n      lastTrigger: trigger,\n      lastSignature: signature,\n      lastError: null,\n      updatedAt: new Date(),\n    })\n    .where(eq(executionStrategiesTable.id, strategy.id));\n}\n')

print("v7.1 total/realized/unrealized P&L accounting applied.")
